class Node {
  constructor(tag="div") { this.tagName=tag.toUpperCase();this.children=[];this.dataset={};this.attrs={};this.value="";this.hidden=false;this.disabled=false;this.className="";this._text=""; }
  set textContent(value){this._text=String(value ?? "");this.children=[];}
  get textContent(){return this._text+this.children.map(child=>child.textContent).join("");}
  append(...nodes){for(const node of nodes){node.parent=this;this.children.push(node);}}
  replaceChildren(...nodes){this._text="";this.children=[];this.append(...nodes);}
  replaceWith(node){if(!this.parent)return;const owner=this.parent,index=owner.children.indexOf(this);if(index>=0){owner.children[index]=node;node.parent=owner;this.parent=null;}}
  remove(){if(this.parent){this.parent.children=this.parent.children.filter(node=>node!==this);this.parent=null;}}
  insertBefore(node,before){const index=this.children.indexOf(before);if(index<0)this.append(node);else{this.children.splice(index,0,node);node.parent=this;}}

  setAttribute(key,value){this.attrs[key]=String(value);}
  removeAttribute(key){delete this.attrs[key];}
  matches(selector){return selector.startsWith(".")?this.className.split(" ").includes(selector.slice(1)):selector.startsWith("#")?this.id===selector.slice(1):this.tagName.toLowerCase()===selector;}
  querySelectorAll(selector){const output=[];for(const child of this.children){if(child.matches(selector))output.push(child);output.push(...child.querySelectorAll(selector));}return output;}
  querySelector(selector){return this.querySelectorAll(selector)[0] || null;}
  reportValidity(){return true;} checkValidity(){return true;} reset(){} focus(){} scrollIntoView(){}
  setSelectionRange(start,end){this.selectionStart=start;this.selectionEnd=end;}
  getContext(){return {drawImage(){},fillRect(){},strokeRect(){}};}
  getBoundingClientRect(){return {left:10,top:20,width:400,height:200};}
  showModal(){this.open=true;} close(){this.open=false;}
}
